/** Hàng sao bấm được. */
function StarRow({
  value,
  onChange,
  size = 28,
  starLabel,
}: {
  value: number;
  onChange: (v: number) => void;
  size?: number;
  starLabel: (n: number) => string;
}) {
  return (
    <div className="flex items-center gap-1">
      {[1, 2, 3, 4, 5].map((s) => (
        <button
          key={s}
          type="button"
          aria-label={starLabel(s)}
          onClick={() => onChange(value === s ? 0 : s)}
          className="transition-transform active:scale-90"
        >
          <Star
            style={{ width: size, height: size }}
            className={
              s <= value
                ? "fill-[#FACC15] text-[#FACC15]"
                : "fill-neutral-200 text-neutral-200"
            }
          />
        </button>
      ))}
    </div>
  );
}

/** Chip chọn (tag / điểm nổi bật). */
function Chip({
  label,
  active,
  onClick,
  icon,
}: {
  label: string;
  active: boolean;
  onClick: () => void;
  icon?: React.ReactNode;
}) {
  return (
    <button
      type="button"
      onClick={onClick}
      className={`inline-flex items-center gap-1.5 rounded-full border px-3 py-1.5 text-xs font-medium transition-colors ${
        active
          ? "border-emerald-500 bg-emerald-50 text-emerald-700"
          : "border-neutral-200 bg-white text-neutral-600 hover:bg-neutral-50"
      }`}
    >
      {icon && <span className="shrink-0">{icon}</span>}
      {label}
    </button>
  );
}

function ratingBadge(stars: number, label: string) {
  if (stars <= 0) return null;
  const tone =
    stars <= 2 ? "text-red-500" : stars === 3 ? "text-amber-600" : "text-emerald-600";
  // `whitespace-nowrap` + `shrink-0` để label không bị wrap 2 dòng khi
  // parent flex hẹp (vd mobile: "Bình thường" rớt thành "Bình" / "thường").
  // Width của badge cố định theo độ dài text, label item bên cạnh dùng
  // `min-w-0` + `truncate` để nhường chỗ.
  return (
    <span className={`shrink-0 whitespace-nowrap text-[11px] font-semibold ${tone}`}>
      {label}
    </span>
  );
}

export default function ReviewPage() {
  const t = useTranslations("review");
  const tCommon = useTranslations("common");
  const router = useRouter();
  const { orderId } = useParams<{ orderId: string }>();
  const searchParams = useSearchParams();
  const orderCode = searchParams.get("code");
  // Format money in the ORDER's own currency (not the ambient selected branch).
  const [currency, setCurrency] = useState("JPY");
  const fmt = (v: number) => formatMoney(v, currency);

  // i18n content arrays/objects (next-intl `t.raw` returns the raw JSON value).
  const RATING_LABELS = t.raw("ratingLabels") as string[];
  const DISH_TAGS = t.raw("dishTags") as string[];
  const ASPECT_TAGS = t.raw("aspectTags") as string[];
  const HIGHLIGHTS = t.raw("highlights") as string[];
  const aspectText = t.raw("aspects") as Record<AspectKey, { label: string; hint: string }>;
  const ASPECTS = ASPECT_META.map((a) => ({ ...a, ...aspectText[a.key] }));
  const starLabel = (n: number) => t("starAriaLabel", { count: n });

  const [loading, setLoading] = useState(true);
  const [items, setItems] = useState<ReviewableItem[]>([]);
  const [submitting, setSubmitting] = useState(false);
  const [successModalOpen, setSuccessModalOpen] = useState(false);

  // Overall + per-aspect + per-dish state
  const [overall, setOverall] = useState(0);
  const [dishReviews, setDishReviews] = useState<Record<string, RatingBlock>>({});
  const [aspects, setAspects] = useState<Record<AspectKey, RatingBlock>>({
    service: emptyBlock(),
    staff: emptyBlock(),
    space: emptyBlock(),
  });
  const [highlights, setHighlights] = useState<string[]>([]);
  const [generalComment, setGeneralComment] = useState("");
  // Photos: each carries the SERVER file id (for submit) + URL (for preview).
  const [photos, setPhotos] = useState<{ id: string; url: string }[]>([]);
  const [uploadingPhotos, setUploadingPhotos] = useState(false);

  useEffect(() => {
    let cancelled = false;
    (async () => {
      try {
        const { currency: orderCurrency, items: list } = await getReviewable(orderId);
        if (cancelled) return;
        setCurrency(orderCurrency);
        const pending = list.filter((i) => !i.already_reviewed);
        setItems(pending);
        setDishReviews(Object.fromEntries(pending.map((i) => [i.order_item_id, emptyBlock()])));
      } catch (error) {
        console.error("Review API error:", error);
        if (!cancelled) toast.error(t("loadError"));
      } finally {
        if (!cancelled) setLoading(false);
      }
    })();
    return () => {
      cancelled = true;
    };
  }, [orderId, t]);

  const reviewedDishCount = useMemo(
    () => Object.values(dishReviews).filter((d) => d.stars > 0).length,
    [dishReviews],
  );

  const canSubmit =
    overall > 0 ||
    reviewedDishCount > 0 ||
    Object.values(aspects).some((a) => a.stars > 0) ||
    generalComment.trim().length > 0;

  function patchDish(id: string, patch: Partial<RatingBlock>) {
    setDishReviews((prev) => ({ ...prev, [id]: { ...prev[id], ...patch } }));
  }
  function toggleDishTag(id: string, tag: string) {
    setDishReviews((prev) => {
      const cur = prev[id];
      const tags = cur.tags.includes(tag) ? cur.tags.filter((t) => t !== tag) : [...cur.tags, tag];
      return { ...prev, [id]: { ...cur, tags } };
    });
  }
  function patchAspect(key: AspectKey, patch: Partial<RatingBlock>) {
    setAspects((prev) => ({ ...prev, [key]: { ...prev[key], ...patch } }));
  }
  function toggleAspectTag(key: AspectKey, tag: string) {
    setAspects((prev) => {
      const cur = prev[key];
      const tags = cur.tags.includes(tag) ? cur.tags.filter((t) => t !== tag) : [...cur.tags, tag];
      return { ...prev, [key]: { ...cur, tags } };
    });
  }
  async function onPickPhotos(e: React.ChangeEvent<HTMLInputElement>) {
    const files = Array.from(e.target.files ?? []).slice(0, 6 - photos.length);
    e.target.value = "";
    if (files.length === 0) return;
    setUploadingPhotos(true);
    try {
      // Upload ngay lên server → nhận file id + url thật để preview + submit.
      const uploaded = await uploadReviewPhotos(orderId, files);
      setPhotos((p) => [...p, ...uploaded]);
    } catch {
      toast.error(t("photoUploadError"));
    } finally {
      setUploadingPhotos(false);
    }
  }

  async function handleSubmit() {
    if (!canSubmit) return;
    setSubmitting(true);
    try {
      // 1) Per-dish → sao 1-5 + tags + comment (BE plan-026 lưu đầy đủ).
      const dishPayload = items
        .filter((i) => dishReviews[i.order_item_id]?.stars > 0)
        .map((i) => {
          const b = dishReviews[i.order_item_id];
          return {
            order_item_id: i.order_item_id,
            product_id: i.product_id,
            rating: b.stars,
            tags: b.tags.length ? b.tags : null,
            comment: b.comment.trim() || null,
          };
        });
      if (dishPayload.length > 0) {
        await submitReviews(orderId, { reviews: dishPayload });
      }

      // 2) Branch review = tổng thể + aspects (dịch vụ/nhân viên/không gian)
      //    + điểm nổi bật + nhận xét chung. (Ảnh: TODO — cần media upload infra.)
      if (overall > 0) {
        const aspectComments = ASPECTS.filter((a) => aspects[a.key].comment.trim())
          .map((a) => `${a.label}: ${aspects[a.key].comment.trim()}`)
          .join(" | ");
        const comment = [generalComment.trim(), aspectComments].filter(Boolean).join(" | ") || null;
        await submitBranchReview(orderId, {
          rating: overall,
          service_rating: aspects.service.stars || null,
          staff_rating: aspects.staff.stars || null,
          space_rating: aspects.space.stars || null,
          highlights: highlights.length ? highlights : null,
          photo_file_ids: photos.length ? photos.map((p) => p.id) : null,
          comment,
        });
      }

      // Hiện modal thành công thay vì toast + back
      setSuccessModalOpen(true);
    } catch {
      toast.error(t("submitError"));
    } finally {
      setSubmitting(false);
    }
  }

  if (loading) {
    // Cùng khung với /orders + /orders/[id]: giữ global Header khi loading để
    // trang không "nhảy" khi dữ liệu về.
    return (
      <div className="flex min-h-screen flex-col bg-[#FAFAFA]">
        <Header showLogo hideSwitcher hideRegister />
        <div className="flex flex-1 items-center justify-center">
          <Loader2 className="size-8 animate-spin text-primary" />
        </div>
      </div>
    );
  }

  return (
    <div className="flex min-h-screen flex-col bg-[#FAFAFA] overflow-x-clip">
      {/* `hideShadow` để mobile không có gạch ngang giữa global header và
          sub-header sticky bên dưới — match pattern /orders, /checkout. */}
      <Header showLogo hideSwitcher hideOrderCta hideShadow hideRegister />

      {/* Sub-header: back + tiêu đề.
          - Mobile: sticky `top-12 z-30 bg-white` + border-b để tách lớp khi
            scroll qua (Header mobile cao h-12).
          - Desktop: non-sticky, bg-#FAFAFA cùng page, `md:border-b-0` tránh
            duplicate với shadow của global Header. Container `md:max-w-7xl`
            để tiêu đề align cùng cột dọc với logo trong Header.
          Pattern lấy nguyên từ /orders + /orders/[id]. */}
      <div className="sticky top-12 z-30 border-b border-neutral-200 bg-white md:static md:top-auto md:z-auto md:border-b-0 md:bg-[#FAFAFA]">
        <div className="mx-auto flex w-full max-w-5xl items-center gap-2 px-4 py-3 md:max-w-7xl md:px-6 md:py-4">
          <button
            onClick={() => router.back()}
            aria-label={tCommon("back")}
            className="-ml-1 flex size-7 items-center justify-center rounded-lg text-neutral-700 transition-colors hover:bg-muted"
          >
            <ArrowLeft className="size-5" />
          </button>
          <h1 className="truncate text-base font-bold text-neutral-900">{t("pageTitle")}</h1>
          {orderCode && (
            <span className="ml-auto shrink-0 text-xs text-neutral-400">#{shortOrderCode(orderCode)}</span>
          )}
        </div>
      </div>

      {/* Body: 1 cột (mobile) / 2 cột (desktop) */}
      <div className="mx-auto w-full max-w-5xl flex-1 lg:grid lg:grid-cols-[minmax(0,1fr)_340px] lg:items-start lg:gap-6 lg:px-6 lg:py-4">
        <main className="space-y-3 px-4 py-4 pb-28 lg:p-0 lg:pb-4">
        {/* Trải nghiệm tổng thể */}
        <section className="rounded-2xl border border-neutral-200 bg-white p-4">
          <h2 className="-mx-4 mb-3 border-b border-neutral-100 px-4 pb-3 text-sm font-bold text-neutral-900">{t("overallTitle")}</h2>
          <div className="flex items-start justify-between gap-1 py-2">
            {[1, 2, 3, 4, 5].map((s) => (
              <button
                key={s}
                type="button"
                aria-label={starLabel(s)}
                onClick={() => setOverall(overall === s ? 0 : s)}
                className="flex flex-1 flex-col items-center gap-2 transition-transform active:scale-95"
              >
                <Star
                  style={{ width: 36, height: 36 }}
                  className={s <= overall ? "fill-[#FACC15] text-[#FACC15]" : "fill-neutral-200 text-neutral-200"}
                />
                <span className={`text-[9px] ${s === overall ? "font-semibold text-neutral-700" : "text-neutral-400"}`}>
                  {RATING_LABELS[s]}
                </span>
              </button>
            ))}
          </div>
        </section>

        {/* Đánh giá từng món */}
        {items.length > 0 && (
          <section className="rounded-2xl border border-neutral-200 bg-white p-4">
            <div className="-mx-4 mb-3 flex items-center justify-between border-b border-neutral-100 px-4 pb-3">
              <h2 className="text-sm font-bold text-neutral-900">{t("dishesTitle")}</h2>
              <span className="text-xs text-neutral-400">
                {t("dishProgress", { reviewed: reviewedDishCount, total: items.length })}
              </span>
            </div>
            <div className="space-y-4">
              {items.map((item) => {
                const b = dishReviews[item.order_item_id] ?? emptyBlock();
                return (
                  <div key={item.order_item_id} className="border-b border-neutral-100 pb-4 last:border-0 last:pb-0">
                    <div className="flex items-start gap-3">
                      <div className="size-12 shrink-0 overflow-hidden rounded-lg bg-neutral-100">
                        {item.image ? (
                          // eslint-disable-next-line @next/next/no-img-element
                          <img src={item.image} alt={item.name} className="h-full w-full object-cover" />
                        ) : null}
                      </div>
                      <div className="min-w-0 flex-1">
                        <div className="flex items-start justify-between gap-2">
                          <div className="min-w-0">
                            <p className="truncate text-sm font-semibold text-neutral-900">{item.name}</p>
                            {item.variant_name && (
                              <p className="truncate text-[11px] text-neutral-400">{item.variant_name}</p>
                            )}
                            <p className="mt-0.5 text-xs font-medium text-neutral-500 tabular-nums">{fmt(item.price)}</p>
                          </div>
                          <div className="flex shrink-0 flex-col items-end gap-1">
                            <StarRow value={b.stars} onChange={(v) => patchDish(item.order_item_id, { stars: v })} size={18} starLabel={starLabel} />
                            {ratingBadge(b.stars, RATING_LABELS[b.stars])}
                          </div>
                        </div>
                      </div>
                    </div>
                    {/* Quick tags — thẳng hàng với mép ảnh (full width dưới) */}
                    <div className="mt-3 flex flex-wrap gap-1.5">
                      {DISH_TAGS.map((tag) => (
                        <Chip
                          key={tag}
                          label={tag}
                          active={b.tags.includes(tag)}
                          onClick={() => toggleDishTag(item.order_item_id, tag)}
                        />
                      ))}
                      <button
                        type="button"
                        onClick={() => patchDish(item.order_item_id, { showComment: !b.showComment })}
                        className="rounded-full border border-dashed border-neutral-300 px-3 py-1.5 text-xs text-neutral-500 hover:bg-neutral-50"
                      >
                        {t("addComment")}
                      </button>
                    </div>
                    {b.showComment && (
                      <Textarea
                        value={b.comment}
                        onChange={(e) => patchDish(item.order_item_id, { comment: e.target.value })}
                        placeholder={t("commentForDish", { name: item.name })}
                        className="mt-2 min-h-[60px] text-sm"
                        maxLength={300}
                      />
                    )}
                  </div>
                );
              })}
            </div>
          </section>
        )}

        {/* Dịch vụ & Nhân viên */}
        <section className="rounded-2xl border border-neutral-200 bg-white p-4">
          <h2 className="mb-3 text-sm font-bold text-neutral-900">{t("serviceTitle")}</h2>
          <div className="space-y-4">
            {ASPECTS.map(({ key, label, icon: Icon, hint }) => {
              const b = aspects[key];
              return (
                <div key={key} className="border-b border-neutral-100 pb-4 last:border-0 last:pb-0">
                  <div className="flex items-start gap-3">
                    <div className="flex size-9 shrink-0 items-center justify-center rounded-lg bg-neutral-100 text-neutral-500">
                      <Icon className="size-7" />
                    </div>
                    <div className="min-w-0 flex-1">
                      <div className="flex items-start justify-between gap-2">
                        <div className="min-w-0">
                          <p className="text-sm font-semibold text-neutral-900">{label}</p>
                          <p className="truncate text-[11px] text-neutral-400">{hint}</p>
                        </div>
                        {ratingBadge(b.stars, RATING_LABELS[b.stars])}
                      </div>
                      <div className="flex items-center justify-between gap-2 md:mt-2">
                        <StarRow value={b.stars} onChange={(v) => patchAspect(key, { stars: v })} size={18} starLabel={starLabel} />
                        <button
                          type="button"
                          onClick={() => patchAspect(key, { showComment: !b.showComment })}
                          className="shrink-0 rounded-full border border-dashed border-neutral-300 px-3 py-1.5 text-xs text-neutral-500 hover:bg-neutral-50"
                        >
                          {t("addComment")}
                        </button>
                      </div>
                      {b.showComment && (
                        <div className="mt-2">
                          <Textarea
                            value={b.comment}
                            onChange={(e) => patchAspect(key, { comment: e.target.value })}
                            placeholder={t("commentForAspect", { name: label.toLowerCase() })}
                            className="min-h-[60px] text-sm"
                            maxLength={200}
                          />
                          <div className="mt-1 text-right text-[11px] text-neutral-400">{b.comment.length}/200</div>
                        </div>
                      )}
                    </div>
                  </div>
                </div>
              );
            })}
          </div>
        </section>

        {/* Điểm nổi bật */}
        <section className="rounded-2xl border border-neutral-200 bg-white p-4">
          <h2 className="mb-3 text-sm font-bold text-neutral-900">{t("highlightsTitle")}</h2>
          <div className="flex flex-wrap gap-2">
            {HIGHLIGHTS.map((h, i) => (
              <Chip
                key={h}
                label={h}
                icon={HIGHLIGHT_ICONS[i]}
                active={highlights.includes(h)}
                onClick={() =>
                  setHighlights((prev) => (prev.includes(h) ? prev.filter((x) => x !== h) : [...prev, h]))
                }
              />
            ))}
          </div>
        </section>

        {/* Nhận xét chung */}
        <section className="rounded-2xl border border-neutral-200 bg-white p-4">
          <h2 className="mb-2 text-sm font-bold text-neutral-900">{t("generalCommentTitle")}</h2>
          <Textarea
            value={generalComment}
            onChange={(e) => setGeneralComment(e.target.value)}
            placeholder={t("generalCommentPlaceholder")}
            className="min-h-[88px] text-sm"
            maxLength={500}
          />
          <div className="mt-1 text-right text-[11px] text-neutral-400">{generalComment.length}/500</div>
        </section>

        {/* Thêm ảnh */}
        <section className="rounded-2xl border border-neutral-200 bg-white p-4">
          <h2 className="mb-3 text-sm font-bold text-neutral-900">{t("photosTitle")}</h2>
          <div className="flex flex-wrap gap-2">
            {photos.map((p) => (
              <div key={p.id} className="relative size-20 overflow-hidden rounded-lg border">
                {/* eslint-disable-next-line @next/next/no-img-element */}
                <img src={p.url} alt="" className="h-full w-full object-cover" />
                <button
                  aria-label={tCommon("close")}
                  type="button"
                  onClick={() => setPhotos((prev) => prev.filter((x) => x.id !== p.id))}
                  className="absolute right-1 top-1 flex size-5 items-center justify-center rounded-full bg-black/60 text-white"
                >
                  <X className="size-3" />
                </button>
              </div>
            ))}
            {photos.length < 6 && (
              <label className="flex size-20 cursor-pointer flex-col items-center justify-center gap-1 rounded-lg border border-dashed border-neutral-300 text-neutral-400 hover:bg-neutral-50">
                {uploadingPhotos ? (
                  <Loader2 className="size-5 animate-spin" />
                ) : (
                  <>
                    <ImagePlus className="size-5" />
                    <span className="text-[10px]">{t("addPhoto")}</span>
                  </>
                )}
                <input
                  type="file"
                  accept="image/*"
                  multiple
                  disabled={uploadingPhotos}
                  className="hidden"
                  onChange={onPickPhotos}
                />
              </label>
            )}
          </div>
          {/* Hint "Tối đa 6 ảnh, mỗi ảnh ≤ 5MB…" — ẩn theo yêu cầu UI mới. */}
          <p className="mt-2 hidden text-[11px] text-neutral-400">{t("photoHelp", { max: 6, size: 5 })}</p>
        </section>
        </main>

        {/* Desktop sidebar: card "Đơn hàng" + nút gửi (mobile dùng thanh đáy) */}
        {/* top = global Header h-14 (56px) + 16px thở. Sub-header không còn
            sticky ở desktop nên không cộng chiều cao của nó nữa. */}
        <aside className="hidden lg:block lg:sticky lg:top-[72px]">
          <div className="rounded-2xl border border-neutral-200 bg-white p-4">
            <h2 className="text-sm font-bold text-neutral-900">{t("orderCardTitle")}</h2>
            {orderCode && <p className="mt-0.5 text-xs text-neutral-400">#{shortOrderCode(orderCode)}</p>}
            <div className="mt-3 space-y-2.5">
              {items.map((item) => (
                <div key={item.order_item_id} className="flex items-center gap-2.5">
                  <div className="size-10 shrink-0 overflow-hidden rounded-lg bg-neutral-100">
                    {item.image ? (
                      // eslint-disable-next-line @next/next/no-img-element
                      <img src={item.image} alt={item.name} className="h-full w-full object-cover" />
                    ) : null}
                  </div>
                  <div className="min-w-0 flex-1">
                    <p className="truncate text-sm font-medium text-neutral-900">{item.name}</p>
                    <p className="text-xs text-neutral-500 tabular-nums">{fmt(item.price)}</p>
                  </div>
                </div>
              ))}
            </div>
          </div>
          <Button
            onClick={handleSubmit}
            disabled={!canSubmit || submitting}
            className="mt-4 h-12 w-full bg-emerald-600 text-base font-semibold hover:bg-emerald-700 disabled:opacity-50"
          >
            {submitting ? <Loader2 className="size-5 animate-spin" /> : t("submit")}
          </Button>
        </aside>
      </div>

      {/* Submit - thanh cố định đáy (mobile) */}
      <div className="fixed bottom-0 left-0 right-0 z-20 border-t bg-white lg:hidden">
        <div className="mx-auto w-full max-w-2xl px-4 py-3">
          <Button
            onClick={handleSubmit}
            disabled={!canSubmit || submitting}
            className="h-12 w-full bg-emerald-600 text-base font-semibold hover:bg-emerald-700 disabled:opacity-50"
          >
            {submitting ? <Loader2 className="size-5 animate-spin" /> : t("submit")}
          </Button>
        </div>
      </div>

      {/* Success Modal — chỉ đóng được qua nút "Hoàn tất" (gọi
          `setSuccessModalOpen(false)` trực tiếp). Backdrop click bị chặn bởi
          `disablePointerDismissal`; escape / focus-out bị filter bằng
          `reason` trong onOpenChange; nút X bị ẩn bằng `showCloseButton={false}`. */}
      <Dialog
        open={successModalOpen}
        onOpenChange={(next, eventDetails) => {
          if (!next && eventDetails?.reason !== "close-press" && eventDetails?.reason !== "imperative-action") {
            return;
          }
          setSuccessModalOpen(next);
        }}
        disablePointerDismissal
      >
        <DialogContent className="max-w-sm p-0" showCloseButton={false}>
          <style jsx global>{`
            @keyframes draw-circle {
              to { stroke-dashoffset: 0; }
            }
            @keyframes scale-in {
              from { transform: scale(0); }
              to { transform: scale(1); }
            }
            @keyframes draw-check {
              to { stroke-dashoffset: 0; }
            }
            @keyframes pulse-success {
              0%, 100% { box-shadow: 0px 4px 6px -4px #5EE83066, 0px 10px 15px -3px #5EE83066, 0 0 0 0 rgba(41, 146, 54, 0.4); }
              50% { box-shadow: 0px 4px 6px -4px #5EE83066, 0px 10px 15px -3px #5EE83066, 0 0 0 10px rgba(41, 146, 54, 0); }
            }
          `}</style>

          <div className="relative p-6 pt-8">
            {/* Success Icon */}
            <div className="relative mx-auto mb-6 size-20">
              {/* Animated ring */}
              <svg
                width="80"
                height="80"
                viewBox="0 0 80 80"
                style={{ position: 'absolute', top: '50%', left: '50%', transform: 'translate(-50%, -50%) rotate(-90deg)' }}
              >
                <circle
                  cx="40"
                  cy="40"
                  r="36"
                  fill="none"
                  stroke="#299236"
                  strokeWidth="4"
                  strokeLinecap="round"
                  style={{
                    strokeDasharray: 226,
                    strokeDashoffset: 226,
                    animation: 'draw-circle 0.8s ease-out forwards',
                  }}
                />
              </svg>

              {/* Success circle */}
              <div
                className="size-20 rounded-full flex items-center justify-center"
                style={{
                  backgroundColor: '#299236',
                  boxShadow: '0px 4px 6px -4px #5EE83066, 0px 10px 15px -3px #5EE83066',
                  animation: 'scale-in 0.4s 0.6s cubic-bezier(0.175, 0.885, 0.32, 1.275) backwards, pulse-success 2s 1.5s ease-in-out infinite',
                }}
              >
                <svg width="40" height="40" viewBox="0 0 40 40" fill="none">
                  <path
                    d="M10 20 L18 28 L30 12"
                    stroke="white"
                    strokeWidth="4"
                    strokeLinecap="round"
                    strokeLinejoin="round"
                    style={{
                      strokeDasharray: 30,
                      strokeDashoffset: 30,
                      animation: 'draw-check 0.5s 0.8s ease-out forwards',
                    }}
                  />
                </svg>
              </div>
            </div>

            {/* Title */}
            <h2 className="mb-2 text-center text-lg font-semibold text-neutral-900">
              {t("successTitle")}
            </h2>

            {/* Description */}
            <p className="mb-4 text-center text-sm text-neutral-600 leading-relaxed">
              {t("successMessage")}
            </p>

            {/* Order Code */}
            {orderCode && (
              <div className="mb-6 text-center">
                <p className="mb-1 text-xs text-neutral-500">{t("orderCodeLabel")}</p>
                <p className="text-2xl font-bold text-neutral-900 tracking-wider">#{shortOrderCode(orderCode)}</p>
              </div>
            )}

            {/* Action Buttons */}
            <div className="space-y-3">
              <Button
                onClick={() => {
                  setSuccessModalOpen(false);
                  // Return về trang menu sau khi đánh giá thành công. URL
                  // được gọi từ order-success kèm `?type=takeaway|dine_in
                  // &shop=...`. Takeaway có trang menu rõ ràng `/takeaway/{shop}`;
                  // dine-in thì order đã đóng, qr_token không nằm trong URL
                  // → fallback home.
                  const type = searchParams.get("type");
                  const shop = searchParams.get("shop");
                  if (type === "takeaway" && shop) {
                    router.push(`/takeaway/${shop}`);
                  } else {
                    router.push("/");
                  }
                }}
                className="w-full h-12"
                style={{ backgroundColor: '#27A14F' }}
              >
                {t("done")}
              </Button>
            </div>
          </div>
        </DialogContent>
      </Dialog>
    </div>
  );
}
